<?php
namespace App\Http\Requests;
use App\Models\Discount; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class SaveDiscountRequest extends FormRequest { public function authorize(): bool { return true; } protected function prepareForValidation(): void { $this->merge(['name'=>trim((string)$this->name),'code'=>($v=trim((string)$this->code))!==''?strtoupper($v):null]); } public function rules(): array { $id=$this->input('id'); return ['id'=>['nullable','integer','exists:discounts,id'],'name'=>['required','string','max:150'],'code'=>['nullable','string','max:50',Rule::unique('discounts','code')->ignore($id)->where(fn($q)=>$q->where('organization_id',auth()->user()->organization_id))],'description'=>['nullable','string','max:2000'],'discount_type'=>['required',Rule::in(array_keys(Discount::typeOptions()))],'applies_to'=>['required',Rule::in(array_keys(Discount::appliesToOptions()))],'value'=>['required','numeric','gt:0'],'max_discount_amount'=>['nullable','numeric','min:0'],'starts_at'=>['nullable','date'],'ends_at'=>['nullable','date','after_or_equal:starts_at'],'usage_limit'=>['nullable','integer','min:1'],'is_active'=>['required','boolean'],'is_combinable'=>['required','boolean'],'requires_reason'=>['required','boolean'],'requires_manager_approval'=>['required','boolean']]; } public function after(): array { return [function($v){ if($this->discount_type==='percentage' && (float)$this->value>100)$v->errors()->add('value','Percentage discounts may not be greater than 100.'); }]; } }
